#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    long long minOperationsForKPeaks(std::vector<int>& nums, int k) {
        int n = nums.size();
        if (k == 0) return 0;
        if (k > (n - 1) / 2) return -1;
        std::vector<int> cost(n, 0);
        for (int i = 1; i < n - 1; ++i) {
            int req = std::max(nums[i - 1], nums[i + 1]) + 1;
            cost[i] = std::max(0, req - nums[i]);
        }
        std::vector<std::vector<long long>> dp(k + 1, std::vector<long long>(n, 1e18));
        for (int i = 0; i < n; ++i) dp[0][i] = 0;
        for (int p = 1; p <= k; ++p) {
            for (int i = 2 * p - 1; i < n - 1; ++i) {
                dp[p][i] = dp[p][i - 1];
                long long prev = i >= 2 ? dp[p - 1][i - 2] : 0;
                dp[p][i] = std::min(dp[p][i], prev + cost[i]);
            }
        }
        long long ans = 1e18;
        for (int i = 0; i < n; ++i) ans = std::min(ans, dp[k][i]);
        return ans;
    }
};

import java.util.*;

class Solution {
    public long minOperationsForKPeaks(int[] nums, int k) {
        int n = nums.length;
        if (k == 0) return 0;
        if (k > (n - 1) / 2) return -1;
        int[] cost = new int[n];
        for (int i = 1; i < n - 1; i++) {
            int req = Math.max(nums[i - 1], nums[i + 1]) + 1;
            cost[i] = Math.max(0, req - nums[i]);
        }
        long[][] dp = new long[k + 1][n];
        for (int p = 1; p <= k; p++) Arrays.fill(dp[p], (long) 1e18);
        for (int p = 1; p <= k; p++) {
            for (int i = 2 * p - 1; i < n - 1; i++) {
                dp[p][i] = dp[p][i - 1];
                long prev = i >= 2 ? dp[p - 1][i - 2] : 0;
                dp[p][i] = Math.min(dp[p][i], prev + cost[i]);
            }
        }
        long ans = (long) 1e18;
        for (int i = 0; i < n; i++) ans = Math.min(ans, dp[k][i]);
        return ans;
    }
}

function minOperationsForKPeaks(nums, k) {
    const n = nums.length;
    if (k === 0) return 0;
    if (k > Math.floor((n - 1) / 2)) return -1;
    const cost = new Array(n).fill(0);
    for (let i = 1; i < n - 1; i++) {
        const req = Math.max(nums[i - 1], nums[i + 1]) + 1;
        cost[i] = Math.max(0, req - nums[i]);
    }
    const dp = Array.from({length: k + 1}, () => new Array(n).fill(Infinity));
    for (let i = 0; i < n; i++) dp[0][i] = 0;
    for (let p = 1; p <= k; p++) {
        for (let i = 2 * p - 1; i < n - 1; i++) {
            dp[p][i] = dp[p][i - 1];
            const prev = i >= 2 ? dp[p - 1][i - 2] : 0;
            dp[p][i] = Math.min(dp[p][i], prev + cost[i]);
        }
    }
    return Math.min(...dp[k]);
}
